def main():
    texts = {R: open(R, encoding="utf-8").read(), S: open(S, encoding="utf-8").read()}
    bad = []
    for i, (f, old, new) in enumerate(REPL, 1):
        n = texts[f].count(old)
        if n != 1: bad.append("replacement %d in %s: the old text occurs %d times (needs exactly 1): %s" % (i, f, n, old[:90]))
    if bad:
        print("NOTHING WRITTEN. Problems:"); [print("  -", b) for b in bad]; return 1
    for f, old, new in REPL: texts[f] = texts[f].replace(old, new)
    for f in (R, S): open(f, "w", encoding="utf-8").write(texts[f])
    print("ok   %d replacements applied (%d in %s, %d in %s)" % (len(REPL), sum(1 for r in REPL if r[0] == R), R, sum(1 for r in REPL if r[0] == S), S)); return 0
if __name__ == "__main__": sys.exit(main())
